const config = {
  githubOwner: "claude-builders-bounty",
  githubRepo: "claude-builders-bounty",
  summaryLanguage: "EN",
  lookbackDays: 7,
  anthropicApiKey: "REPLACE_ME_ANTHROPIC_API_KEY",
  // The Slack webhook URL selects the destination channel for modern Slack apps.
  slackWebhookUrl: "https://hooks.slack.com/services/REPLACE_ME",
  // Optional payload channel for compatible legacy/custom webhook setups.
  slackChannel: "",
};

function requireConfigured(value, name) {
  if (!value || String(value).includes("REPLACE_ME")) {
    throw new Error(`${name} must be configured before running the workflow.`);
  }
}

if (!["EN", "FR"].includes(config.summaryLanguage)) {
  throw new Error("summaryLanguage must be EN or FR.");
}

if (!Number.isFinite(config.lookbackDays) || config.lookbackDays < 1 || config.lookbackDays > 31) {
  throw new Error("lookbackDays must be a number from 1 to 31.");
}

requireConfigured(config.githubOwner, "githubOwner");
requireConfigured(config.githubRepo, "githubRepo");
requireConfigured(config.anthropicApiKey, "anthropicApiKey");
requireConfigured(config.slackWebhookUrl, "slackWebhookUrl");

return [{ json: config }];

const config = $input.first().json;
const DAY_MS = 24 * 60 * 60 * 1000;

const end = new Date();
const start = new Date(end.getTime() - config.lookbackDays * DAY_MS);
const startDate = start.toISOString().slice(0, 10);
const endDate = end.toISOString().slice(0, 10);
const repository = `${config.githubOwner}/${config.githubRepo}`;

function githubUrl(path, params) {
  const query = Object.entries(params)
    .map(([key, value]) => `${encodeURIComponent(key)}=${encodeURIComponent(String(value))}`)
    .join("&");
  return `https://api.github.com${path}?${query}`;
}

return [
  {
    json: {
      ...config,
      repository,
      periodStart: start.toISOString(),
      periodEnd: end.toISOString(),
      periodStartDate: startDate,
      periodEndDate: endDate,
      commitsUrl: githubUrl(`/repos/${repository}/commits`, {
        since: start.toISOString(),
        until: end.toISOString(),
        per_page: 100,
      }),
      closedIssuesUrl: githubUrl("/search/issues", {
        q: `repo:${repository} type:issue is:closed closed:${startDate}..${endDate}`,
        per_page: 50,
      }),
      mergedPullRequestsUrl: githubUrl("/search/issues", {
        q: `repo:${repository} type:pr is:merged merged:${startDate}..${endDate}`,
        per_page: 50,
      }),
    },
  },
];

function nodeJson(nodeName) {
  const items = $(nodeName).all();

  if (items.length === 0) {
    return null;
  }

  if (items.length === 1) {
    return items[0].json;
  }

  return items.map((item) => item.json);
}

function asArray(value) {
  if (Array.isArray(value)) {
    return value;
  }

  if (value && Array.isArray(value.body)) {
    return value.body;
  }

  if (value && Array.isArray(value.items)) {
    return value.items;
  }

  if (value && value.body && Array.isArray(value.body.items)) {
    return value.body.items;
  }

  if (value && typeof value === "object" && Object.keys(value).every((key) => /^\d+$/.test(key))) {
    return Object.keys(value)
      .sort((a, b) => Number(a) - Number(b))
      .map((key) => value[key]);
  }

  return [];
}

const config = $("Build GitHub API URLs").first().json;
const commits = asArray(nodeJson("GitHub Commits"));
const closedIssues = asArray(nodeJson("GitHub Closed Issues"));
const mergedPullRequests = asArray(nodeJson("GitHub Merged Pull Requests"));

const activity = {
  repository: config.repository,
  period: {
    start: config.periodStart,
    end: config.periodEnd,
  },
  commits: commits.map((commit) => ({
    sha: commit.sha,
    title: commit.commit?.message?.split("\n")[0] || "",
    author: commit.commit?.author?.name || commit.author?.login || "unknown",
    date: commit.commit?.author?.date || commit.commit?.committer?.date || "",
    url: commit.html_url,
  })),
  closedIssues: closedIssues.map((issue) => ({
    number: issue.number,
    title: issue.title,
    author: issue.user?.login || "unknown",
    closedAt: issue.closed_at,
    url: issue.html_url,
  })),
  mergedPullRequests: mergedPullRequests.map((pullRequest) => ({
    number: pullRequest.number,
    title: pullRequest.title,
    author: pullRequest.user?.login || "unknown",
    mergedAt: pullRequest.closed_at,
    url: pullRequest.html_url,
  })),
};

const outputLanguage = config.summaryLanguage === "FR" ? "French" : "English";
const prompt = [
  `Write a weekly engineering narrative summary in ${outputLanguage}.`,
  `Repository: ${config.repository}`,
  `Period: ${config.periodStartDate} through ${config.periodEndDate}`,
  "",
  "Use this structure:",
  "1. Headline",
  "2. What changed",
  "3. Notable issues closed",
  "4. Merged pull requests",
  "5. Suggested follow-ups",
  "",
  "Keep it concise, useful for a development team, and cite issue or PR numbers when present.",
  "",
  "GitHub activity JSON:",
  JSON.stringify(activity, null, 2),
].join("\n");

return [
  {
    json: {
      ...config,
      commitCount: activity.commits.length,
      closedIssueCount: activity.closedIssues.length,
      mergedPullRequestCount: activity.mergedPullRequests.length,
      activity,
      claudeBody: {
        model: "claude-sonnet-4-20250514",
        max_tokens: 1200,
        system: "You write clear weekly software development updates from GitHub activity data.",
        messages: [
          {
            role: "user",
            content: prompt,
          },
        ],
      },
    },
  },
];

const config = $("Prepare Claude Request").first().json;
const claudeResponse = $("Claude Summary").first().json;

const summary = (claudeResponse.content || [])
  .filter((part) => part.type === "text")
  .map((part) => part.text)
  .join("\n")
  .trim();

if (!summary) {
  throw new Error("Claude API returned no text summary.");
}

const slackPayload = {
  text: summary,
  mrkdwn: true,
};

if (config.slackChannel) {
  slackPayload.channel = config.slackChannel;
}

return [
  {
    json: {
      repository: config.repository,
      periodStart: config.periodStart,
      periodEnd: config.periodEnd,
      language: config.summaryLanguage,
      commitCount: config.commitCount,
      closedIssueCount: config.closedIssueCount,
      mergedPullRequestCount: config.mergedPullRequestCount,
      slackWebhookUrl: config.slackWebhookUrl,
      slackChannel: config.slackChannel || "webhook default",
      slackPayload,
      summary,
      generatedAt: new Date().toISOString(),
    },
  },
];

const preparedMessage = $("Prepare Slack Message").first().json;
const slackResponse = $("Send Slack Summary").first().json;
const slackStatusCode = Number(slackResponse.statusCode ?? slackResponse.status ?? 0);
const slackResponseBody = String(slackResponse.body ?? slackResponse.data ?? "").trim();

if (!Number.isInteger(slackStatusCode) || slackStatusCode < 200 || slackStatusCode >= 300) {
  throw new Error(`Slack webhook returned unexpected status code: ${slackStatusCode || "missing"}.`);
}

if (slackResponseBody && slackResponseBody !== "ok") {
  throw new Error(`Slack webhook returned unexpected body: ${slackResponseBody}.`);
}

return [
  {
    json: {
      status: "delivered",
      destination: "slack",
      repository: preparedMessage.repository,
      periodStart: preparedMessage.periodStart,
      periodEnd: preparedMessage.periodEnd,
      language: preparedMessage.language,
      commitCount: preparedMessage.commitCount,
      closedIssueCount: preparedMessage.closedIssueCount,
      mergedPullRequestCount: preparedMessage.mergedPullRequestCount,
      slackChannel: preparedMessage.slackChannel,
      slackStatusCode,
      slackResponseBody: slackResponseBody || "empty",
      summary: preparedMessage.summary,
      deliveredAt: new Date().toISOString(),
    },
  },
];
